const msg = $json.message || {};
const chat = msg.chat || {};
const from = msg.from || {};
const text = String(msg.text || '').trim();

const CHAT_ID_AUTORIZADO = REPLACE_WITH_TELEGRAM_CHAT_ID;

// Segurança: só responde ao Renato, somente mensagens humanas e somente texto.
if (from.is_bot === true) return [];
if (Number(chat.id) !== CHAT_ID_AUTORIZADO) return [];
if (!text) return [];

return [{
  json: {
    chatId: chat.id,
    firstName: chat.first_name || 'Renato',
    userMessage: text,
    receivedAt: new Date().toISOString()
  }
}];

const input = $input.first().json;
const telegram = $('Validar e Normalizar Mensagem Telegram').first().json;

let raw = input.output ?? input.text ?? input.response ?? input.result ?? input;
if (typeof raw !== 'string') raw = JSON.stringify(raw);
raw = raw.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
const match = raw.match(/\{[\s\S]*\}/);
if (match) raw = match[0];

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  const msg = (telegram.userMessage || '').toLowerCase();

  // Cumprimentos ou mensagens vagas não disparam busca.
  if (/^(oi|olá|ola|bom dia|boa tarde|boa noite|obrigado|valeu|teste)$/i.test(msg.trim())) {
    parsed = {
      deve_buscar: false,
      intencao: 'conversa',
      query_gmail: '',
      limite: 0,
      resposta_curta: 'Olá, Renato! Estou pronto para te ajudar a consultar seus e-mails. Você pode perguntar, por exemplo: quais e-mails urgentes chegaram hoje?'
    };
  } else {
    let query = 'newer_than:7d';
    if (msg.includes('urg')) query = 'label:Urgente newer_than:7d';
    else if (msg.includes('finance') || msg.includes('boleto') || msg.includes('pagamento') || msg.includes('nota fiscal') || msg.includes('cobrança')) query = 'label:Financeiro newer_than:7d';
    else if (msg.includes('ia') || msg.includes('gemini') || msg.includes('vertex') || msg.includes('openai') || msg.includes('claude')) query = 'label:IA newer_than:7d';
    else if (msg.includes('curso') || msg.includes('aula') || msg.includes('treinamento') || msg.includes('webinar')) query = 'label:Cursos newer_than:7d';
    else if (msg.includes('spam') || msg.includes('suspeito') || msg.includes('phishing') || msg.includes('golpe')) query = 'label:"Spam/Suspeito" newer_than:7d';
    else if (msg.includes('publicidade') || msg.includes('promo') || msg.includes('oferta') || msg.includes('desconto')) query = 'label:Publicidade newer_than:7d';
    else if (msg.includes('newsletter') || msg.includes('novidade')) query = 'label:Newsletter newer_than:7d';
    else if (msg.includes('trabalho') || msg.includes('cliente') || msg.includes('proposta') || msg.includes('reuni')) query = 'label:Trabalho newer_than:7d';
    if (msg.includes('hoje')) query = query.replace('newer_than:7d', 'newer_than:1d');
    parsed = { deve_buscar: true, intencao: 'buscar_emails', query_gmail: query, limite: 5, resposta_curta: '' };
  }
}

const deveBuscar = parsed.deve_buscar === true;
let limite = Number(parsed.limite || 5);
if (!Number.isFinite(limite) || limite <= 0) limite = 5;
if (limite > 10) limite = 10;

return [{
  json: {
    chatId: telegram.chatId,
    firstName: telegram.firstName,
    userMessage: telegram.userMessage,
    deveBuscar,
    intencao: parsed.intencao || (deveBuscar ? 'buscar_emails' : 'conversa'),
    query_gmail: deveBuscar ? String(parsed.query_gmail || 'newer_than:7d') : '',
    limite: deveBuscar ? limite : 0,
    resposta_curta: parsed.resposta_curta || 'Renato, posso te ajudar a consultar seus e-mails. Me diga o que você quer buscar.',
    rawInterpreterResponse: raw
  }
}];

const busca = $input.first().json;
const consulta = $('Normalizar Consulta Gmail').first().json;
const messages = busca.messages || [];

if (!messages.length) {
  return [{
    json: {
      semResultados: true,
      chatId: consulta.chatId,
      query_gmail: consulta.query_gmail,
      userMessage: consulta.userMessage
    }
  }];
}

return messages.map(m => ({
  json: {
    semResultados: false,
    id: m.id,
    threadId: m.threadId,
    chatId: consulta.chatId,
    query_gmail: consulta.query_gmail,
    userMessage: consulta.userMessage
  }
}));

function decodeBase64Url(data) {
  if (!data) return '';
  try {
    const normalized = data.replace(/-/g, '+').replace(/_/g, '/');
    return Buffer.from(normalized, 'base64').toString('utf8');
  } catch (e) {
    return '';
  }
}

function findBody(payload) {
  if (!payload) return '';
  if (payload.mimeType === 'text/plain' && payload.body?.data) return decodeBase64Url(payload.body.data);
  if (payload.parts) {
    for (const part of payload.parts) {
      const found = findBody(part);
      if (found) return found;
    }
  }
  if (payload.body?.data) return decodeBase64Url(payload.body.data);
  return '';
}

function header(headers, name) {
  return (headers || []).find(h => String(h.name).toLowerCase() === name.toLowerCase())?.value || '';
}

const items = $input.all();
const consulta = $('Normalizar Consulta Gmail').first().json;

const emails = items.map((item, index) => {
  const email = item.json;
  const headers = email.payload?.headers || [];
  const from = header(headers, 'From').replace(/</g, '(').replace(/>/g, ')');
  const subject = header(headers, 'Subject') || '(sem assunto)';
  const date = header(headers, 'Date');
  const body = findBody(email.payload) || email.snippet || '';
  const cleanBody = String(body).replace(/\s+/g, ' ').slice(0, 800);
  return `${index + 1}. Assunto: ${subject}
De: ${from}
Data: ${date}
Resumo bruto: ${cleanBody}`;
});

const emailListText = emails.join('\n\n');

return [{
  json: {
    chatId: consulta.chatId,
    userMessage: consulta.userMessage,
    query_gmail: consulta.query_gmail,
    totalEmails: emails.length,
    emailListText
  }
}];

