const input = $input.first().json;
const base = $('Preparar Conteúdo para Resposta').first().json;
let resposta = input.output ?? input.text ?? input.response ?? input.result ?? '';
if (typeof resposta !== 'string') resposta = JSON.stringify(resposta);
resposta = resposta.trim();
if (!resposta) {
  resposta = `Encontrei ${base.totalEmails} e-mail(s), mas não consegui gerar o resumo agora.`;
}
if (resposta.length > 3500) resposta = resposta.slice(0, 3500) + '\n...';
return [{ json: { chatId: base.chatId, respostaTelegram: resposta } }];
